constexpr uint8_t E(AddrMode mode, uint8_t seq) {
    return (uint16_t(mode) << 5) | seq;
}

constexpr AddrMode addr_mode(uint8_t entry) {
    return AddrMode(entry >> 5);
}

constexpr uint8_t inst_seq(uint8_t entry) {
    return entry & 0x1F;
}

