bool InstIns8070::get(uint8_t data) {
    opc = data;
    seq = inst_seq(INST_TABLE[opc]);
    return len() != 0;
}

uint8_t InstIns8070::len() const {
    return INST_LENS[seq];
}

uint8_t InstIns8070::busCycles() const {
    return BUS_CYCLES[seq];
}

uint8_t InstIns8070::externalCycles() const {
    return EXTERNAL_CYCLES[seq];
}

AddrMode InstIns8070::addrMode() const {
    return addr_mode(INST_TABLE[opc]);
}

const char *InstIns8070::sequence() const {
    return BUS_SEQUENCES[seq];
}

MatchWalker::Kind ArchIns8070::cycleKind(const SignalsImpl *impl) const {
    const auto s = static_cast<const Signals *>(impl);
    return s->read()    ? MatchWalker::K_READ
           : s->write() ? MatchWalker::K_WRITE
                        : MatchWalker::K_NONE;
}

// J goes to the operand + 1, as the PC is incremented before a fetch, a
// branch to the next + disp, SSM to the next + 2; A and B are at the
// PC-relative or direct page effective address.
bool ArchIns8070::decode(uint32_t pc, MatchWalker::Decoded &inst) const {
    pc &= 0xFFFF;
    InstIns8070 i;
    if (!i.get(_mems.read_byte(pc)))
        return false;
    inst.pc = pc;
    inst.seq = i.sequence();
    inst.length = i.len();
    const auto next = pc + inst.length;
    const auto disp = static_cast<int8_t>(_mems.read_byte((pc + 1) & 0xFFFF));
    const uint16_t operand = _mems.read_byte((pc + 1) & 0xFFFF) |
                             _mems.read_byte((pc + 2) & 0xFFFF) << 8;
    const auto mode = i.addrMode();
    inst.hasTarget = true;
    if (mode == M_SSM) {
        inst.target = (next + 2) & 0xFFFF;
    } else if (inst.length == 3) {
        inst.target = (operand + 1) & 0xFFFF;
    } else {
        inst.target = (next + disp) & 0xFFFF;
    }
    inst.hasEa = mode == M_DIR || mode == M_DISP;
    inst.ea =
            mode == M_DIR ? 0xFF00 | uint8_t(disp) : uint16_t(next - 1 + disp);
    return true;
}

// The vector table of CALL n: 0020-003E.
// An interrupt pushes the PC, then fetches the next instruction at 0004
// or 0007.
const char *ArchIns8070::interruptSequence() const {
    return "WW?";
}

bool ArchIns8070::isVectorTable(uint32_t addr) const {
    return (addr & ~UINT32_C(0x1E)) == 0x20;
}

void ArchIns8070::markCycle(
        SignalsImpl *impl, MatchWalker::Role role, uint_fast8_t) const {
    static_cast<Signals *>(impl)->markFetch(role == MatchWalker::R_FETCH);
}

